import { supabase } from '../../config/supabase.js';

/**
 * Link-preview pages for shared listings.
 *
 * WHY THIS EXISTS. The website is a Vite SPA: `index.html` is one static file
 * with one static set of Open Graph tags, and the product only appears after
 * React has run. WhatsApp, Telegram, Slack, iMessage and X do NOT run
 * JavaScript when they unfurl a link — they read the HTML that comes back on
 * the first request and nothing else. So `https://…/product/<id>` pasted into
 * WhatsApp shows the generic "Yahora | Keep the Story Going" card for every
 * listing in the marketplace, which is what made a shared link look broken.
 *
 * This route returns real HTML whose OG tags describe THIS listing, and then
 * bounces a human straight on to the SPA. Crawler gets the card, student gets
 * the page.
 *
 * ⚠ THE REDIRECT IS JAVASCRIPT ONLY, DELIBERATELY. A 301/302 would be followed
 * by the crawlers, which would land them back on the SPA's generic tags and
 * undo the whole point. `<meta http-equiv="refresh">` is followed by some of
 * them too. `location.replace()` in a <script> is the one form that every
 * crawler ignores and every browser honours. The <noscript> fallback below is
 * a real, readable card with a link, not a blank page.
 */

/** Where the SPA lives. Overridable per-deploy without a code change. */
const WEB_APP_URL = (process.env.WEB_APP_URL ?? 'https://yahora.netlify.app')
    .trim()
    .replace(/\/+$/, '');

/**
 * Escape for HTML text and double-quoted attributes.
 *
 * Every value below is student-authored (a listing title, a description) and
 * lands inside an attribute. Without this, a title containing `">` closes the
 * meta tag and injects markup into a page we serve — stored XSS, on a route
 * with no auth in front of it.
 */
function escapeHtml(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

/**
 * Only http(s) URLs are echoed into the page.
 *
 * `image_urls` is a text[] the seller's upload writes, so treating it as a URL
 * without checking is how `javascript:` or `data:` gets into an href.
 */
function safeHttpUrl(value) {
    if (!value) return null;
    try {
        const url = new URL(String(value));
        return url.protocol === 'http:' || url.protocol === 'https:' ? url.toString() : null;
    } catch {
        return null;
    }
}

/** ₹1,200 — same formatting the two clients use, so a share matches the app. */
function formatPrice(paise) {
    const value = Number(paise);
    if (!Number.isFinite(value)) return '';
    return `₹${value.toLocaleString('en-IN')}`;
}

/** Trim to a whole word — a description cut mid-word reads like a bug. */
function truncate(text, max) {
    const clean = String(text ?? '').replace(/\s+/g, ' ').trim();
    if (clean.length <= max) return clean;
    const cut = clean.slice(0, max);
    const lastSpace = cut.lastIndexOf(' ');
    return `${(lastSpace > max * 0.6 ? cut.slice(0, lastSpace) : cut).trimEnd()}…`;
}

/**
 * The one-line summary under the title in the preview card:
 *   "₹1,200 · Like new · IIITDM Kurnool — Barely used, comes with the case."
 */
function buildDescription(product) {
    const facts = [
        product.status === 'sold' ? 'SOLD' : formatPrice(product.price),
        product.condition,
        product.university?.name,
    ].filter(Boolean);

    const blurb = truncate(product.description, 110);
    const head = facts.join(' · ');
    return blurb ? `${head} — ${blurb}` : `${head}. On Yahora, your campus marketplace.`;
}

/** The shell both the found and not-found pages use. */
function renderPage({ title, description, image, canonicalUrl, redirectUrl, heading, body }) {
    const safeRedirect = escapeHtml(redirectUrl);
    const imageTag = image
        ? `
    <meta property="og:image" content="${escapeHtml(image)}" />
    <meta property="og:image:alt" content="${escapeHtml(title)}" />
    <meta name="twitter:image" content="${escapeHtml(image)}" />`
        : '';

    return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${escapeHtml(title)}</title>
<link rel="canonical" href="${escapeHtml(canonicalUrl)}" />

<meta property="og:site_name" content="Yahora" />
<meta property="og:type" content="product" />
<meta property="og:title" content="${escapeHtml(title)}" />
<meta property="og:description" content="${escapeHtml(description)}" />
<meta property="og:url" content="${escapeHtml(canonicalUrl)}" />${imageTag}

<meta name="twitter:card" content="${image ? 'summary_large_image' : 'summary'}" />
<meta name="twitter:title" content="${escapeHtml(title)}" />
<meta name="twitter:description" content="${escapeHtml(description)}" />

<style>
  :root { color-scheme: light dark; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #faf7fb; color: #1a1020; padding: 24px;
  }
  .card {
    max-width: 420px; text-align: center; background: #fff; border-radius: 20px;
    padding: 32px 28px; box-shadow: 0 18px 50px rgba(128, 0, 128, 0.12);
  }
  h1 { font-size: 1.25rem; margin: 0 0 8px; }
  p  { margin: 0 0 20px; color: #5b4a63; font-size: 0.95rem; line-height: 1.5; }
  a.btn {
    display: inline-block; padding: 12px 22px; border-radius: 999px;
    background: linear-gradient(135deg, #800080, #d6336c); color: #fff;
    text-decoration: none; font-weight: 600;
  }
  @media (prefers-color-scheme: dark) {
    body { background: #140d18; color: #f6eef8; }
    .card { background: #1f1526; box-shadow: none; }
    p { color: #c3b2cc; }
  }
</style>
</head>
<body>
<div class="card">
  <h1>${escapeHtml(heading)}</h1>
  <p>${escapeHtml(body)}</p>
  <a class="btn" href="${safeRedirect}">Open in Yahora</a>
</div>
<script>window.location.replace(${JSON.stringify(redirectUrl)});</script>
</body>
</html>`;
}

/**
 * GET /share/product/:id
 *
 * Anonymous by design — a crawler has no token, and a listing's title, price
 * and first photo are already public on the cross-campus browse feed.
 *
 * Reads the row directly rather than calling `getProductById`: that handler
 * increments the view counter and joins every comment, so routing previews
 * through it would inflate views on every crawler hit.
 */
export const shareProduct = async (req, res) => {
    const { id } = req.params;
    const fallbackUrl = `${WEB_APP_URL}/product/${encodeURIComponent(id)}`;

    // A bad id must not reach PostgREST as a uuid cast error — that is a 500
    // for something a crawler does constantly.
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id ?? '');

    let product = null;
    if (isUuid) {
        const { data, error } = await supabase
            .from('products')
            .select(`
                id, title, description, price, condition, image_urls, status,
                seller:users!seller_id(full_name),
                university:universities!university_id(name)
            `)
            .eq('id', id)
            .maybeSingle();

        if (error) console.error('Share Product Error:', error);
        product = data ?? null;
    }

    res.set('Content-Type', 'text/html; charset=utf-8');

    if (!product) {
        // 404 status with a real page: the crawler gets a sane card instead of
        // an empty preview, and the student still gets bounced to the site.
        res.status(404).send(
            renderPage({
                title: 'This listing is no longer on Yahora',
                description: 'It may have sold or been taken down. Browse what else is on your campus.',
                image: null,
                canonicalUrl: fallbackUrl,
                redirectUrl: `${WEB_APP_URL}/`,
                heading: 'This listing is gone',
                body: 'It may have sold or been taken down. Taking you to the marketplace…',
            }),
        );
        return;
    }

    const title = `${product.title} — ${formatPrice(product.price)} on Yahora`;

    // Crawled repeatedly and entirely public, so it caches. Five minutes is
    // short enough that a price edit shows up in a re-share the same session.
    res.set('Cache-Control', 'public, max-age=300, s-maxage=300');
    res.status(200).send(
        renderPage({
            title,
            description: buildDescription(product),
            image: safeHttpUrl(product.image_urls?.[0]),
            canonicalUrl: `${WEB_APP_URL}/product/${product.id}`,
            redirectUrl: fallbackUrl,
            heading: product.title,
            body: `${formatPrice(product.price)} · listed by ${product.seller?.full_name ?? 'a student'} on Yahora. Taking you there…`,
        }),
    );
};

export default { shareProduct };
